%[text] # Controller and Environment - Simulation Case
model_name = "HarnessModel_CtrlEnv";
load_system(model_name)

HarnessSetup_CtrlEnv

sim_in = Simulink.SimulationInput(model_name);

sim_in = setBlockParameter(sim_in, ...
  model_name + "/Controller and Environment/Vehicle speed reference", ...
  ReferencedSubsystem = "VehSpdRef_Constant_refsub");

sim_in = setModelParameter(sim_in, StopTime = "100");

applyToModel(sim_in)

sim_out = sim(sim_in);

sim_data = extractTimetable(sim_out.logsout);

% Specify the signal logging names in the model.
signal_names = [
  "Brake force"
  "Motor torque command"
  "Motor heat flow command"
  "Battery heat flow command"
  "Vehicle speed kph"
  "Motor speed"
  "Motor temperature"
  "Battery temperature"
  ];

for idx = 1 : numel(signal_names) %[output:group:0618f42c]
  bev1mus.SignalUtil.plotTimedData( TimedData = sim_data, ... %[output:35b51c99] %[output:632cb7a7] %[output:8e10cc5c] %[output:51dee851] %[output:389fa673] %[output:022820d0] %[output:05aac269] %[output:684ece8b]
    SignalName = signal_names(idx), ... %[output:35b51c99] %[output:632cb7a7] %[output:8e10cc5c] %[output:51dee851] %[output:389fa673] %[output:022820d0] %[output:05aac269] %[output:684ece8b]
    FigureHeight = 100 ) %[output:35b51c99] %[output:632cb7a7] %[output:8e10cc5c] %[output:51dee851] %[output:389fa673] %[output:022820d0] %[output:05aac269] %[output:684ece8b]
end  % for %[output:group:0618f42c]
